const from='hyder@exampleabc.com';
const to='hakpilot@gmail.com';
if(from!=='hyder@exampleabc.com'||to!=='hakpilot@gmail.com')throw Error('QA10 sender or self-only recipient mismatch');
const subject='ExampleABC QA10 - Explicit SendAs Header Test';
const content='Internal ExampleABC Gmail API send-as verification. Sent ONLY to a mailbox owned by the account operator. No customer was contacted.';
const mime=[
 'From: Hyder Khan <'+from+'>',
 'To: '+to,
 'Subject: '+subject,
 'MIME-Version: 1.0',
 'Content-Type: text/plain; charset=UTF-8',
 'Content-Transfer-Encoding: 8bit',
 '',
 content
].join('\r\n');
const raw=Buffer.from(mime,'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
return [{json:{to,from,subject,raw}}];
